class Solution:
    def simplifyPath(self, path: str) -> str:
        parts = path.split('/')
        changed = True
        while changed:
            changed = False
            new_parts = []
            i = 0
            while i < len(parts):
                token = parts[i]
                if token == '' or token == '.':
                    changed = True
                elif token == '..':
                    if new_parts:
                        new_parts.pop()
                    changed = True
                else:
                    new_parts.append(token)
                i += 1
            parts = new_parts
        return '/' + '/'.join(parts)

