class Solution:
    def simplifyPath(self, path: str) -> str:
        stack = []
        token = []
        for ch in path + '/':
            if ch == '/':
                part = "".join(token)
                if part == '..':
                    if stack:
                        stack.pop()
                elif part and part != '.':
                    stack.append(part)
                token = []
            else:
                token.append(ch)
        return '/' + '/'.join(stack)

